<script setup>
import { computed } from 'vue'
const props = defineProps({ items: { type: Array, required: true }, total: String, unit: { type: String, default: 'TB' } })
const gradient = computed(() => { let start = 0; return `conic-gradient(${props.items.map(item => { const stop = start + item.value; const part = `${item.color} ${start}% ${stop}%`; start = stop; return part }).join(',')})` })
</script>
<template><div class="donut-layout"><div class="donut" :style="{background:gradient}" role="img" :aria-label="`UI Mock 文件类型分布：${items.map(i=>i.name+' '+i.value+'%').join('，')}`"><div><strong>{{ total }} <small>{{ unit }}</small></strong><span>UI Mock 样例流量</span></div></div><ul class="donut-legend"><li v-for="item in items" :key="item.name"><i :style="{background:item.color}"/><span>{{ item.name }}</span><b>{{ item.value }}%</b></li></ul></div></template>
